import './style.css';
import { categories, leagues, type Fixture, type Market, type Outcome, type Category } from './data';
import { initialState, resolve, toggleSelection, acceptChanges, totalStake, totalReturn, placementError, placeBets, cashOut, settle, moveOdds, toggleSuspension, searchFixtures, searchReason, removeSuspended, driftOdds, money, round, stakeValue, type State, type Selection, type Bet } from './engine';
import { icon, sportIcon, brandMark } from './icons';
import { restoreSession } from './session';
const root=document.querySelector<HTMLDivElement>('#app')!;
const STORAGE='housebets-sportsbook-v2';
let state:State=initialState();
try { state=restoreSession(localStorage.getItem(STORAGE)); } catch { /* Storage access is optional. */ }
let sport='All sports',competition='All competitions',day='All',query='',category:Category='Popular',onlyFavorites=false,historyTab='Open',busy=false,loading=false;
let notice:{kind:'success'|'error';message:string;bets?:Bet[]}|null=null;
let demoOpen=false,mobileOpen=false,menuOpen=false,walletOpen=false,cashId:string|null=null,resetOpen=false;
let infoPanel:''|'Casino'|'Chat'|'Profile'='';
let liveFeed=true,elapsed=0;
let opener:{key:string;index:number}|undefined;
let toastTimer:ReturnType<typeof setTimeout>|undefined;
let toastText='';
const esc=(v:unknown)=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]!));
const save=()=>{try{localStorage.setItem(STORAGE,JSON.stringify({version:2,favorites:state.favorites,bets:state.bets,balance:state.balance}));}catch{/* Private browsing still works in memory. */}};
const route=()=>location.hash.slice(1)||'/sports';
const routeName=()=>route().startsWith('/match/')?'match':route()==='/live'?'live':route()==='/football'?'football':route()==='/bets'?'bets':'sports';
const currentFixture=()=>state.fixtures.find(f=>f.id===route().split('/')[2])??state.fixtures[0];
const sectionPage=()=>routeName()==='match'?(currentFixture().sport==='Football'?'football':currentFixture().live?'live':'sports'):routeName();
const go=(url:string)=>{if(location.hash===`#${url}`){render();return;}location.hash=url;};
const isLive=(f:Fixture)=>f.live&&!state.noLive;
const kickoff=(f:Fixture)=>new Date(f.kickoff).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});
const dayOf=(f:Fixture)=>{const d=new Date(f.kickoff),t=new Date();t.setHours(0,0,0,0);const diff=Math.round((new Date(d).setHours(0,0,0,0)-t.getTime())/864e5);return diff<=0?'Today':diff===1?'Tomorrow':d.toLocaleDateString([],{weekday:'short'});};
const liveCount=()=>state.noLive?0:state.fixtures.filter(f=>f.live).length;
const favorite=(key:string)=>state.favorites.includes(key);
const plural=(n:number,word:string)=>`${n} ${word}${n===1?'':/(ch|s)$/.test(word)?'es':'s'}`;
const openBets=()=>state.bets.filter(b=>b.status==='open').length;
const currentReturn=()=>round(state.selections.reduce((total,p)=>{const r=resolve(state,p),stake=stakeValue(p.stake);return total+(r&&Number.isFinite(stake)?round(stake*r.outcome.odds):0);},0));
const panelOpen=()=>mobileOpen||menuOpen||demoOpen||walletOpen||!!cashId||resetOpen||!!infoPanel;
const ticking=(f:Fixture)=>f.sport==='Football'&&/^\d+:\d\d$/.test(f.clock);
const clockSeconds=(f:Fixture)=>{const [m,s]=f.clock.split(':').map(Number);const start=m*60+s;return start+elapsed%(90*60-start);};
const clockText=(f:Fixture)=>{if(!ticking(f))return f.clock;const t=clockSeconds(f);return `${Math.floor(t/60)}:${String(t%60).padStart(2,'0')}`;};
const period=(f:Fixture)=>!isLive(f)?`${dayOf(f)} · ${kickoff(f)} UTC`:ticking(f)?clockSeconds(f)<45*60?'1st half':'2nd half':'In play';
const leagueMeta:Record<string,[string,string]>={'Premier League':['PL','#6d3fd6'],'Champions League':['CL','#2f5fc4'],'LaLiga':['LL','#e0552f'],'Serie A':['SA','#1677c9'],'Bundesliga':['BL','#d43a43'],'ATP Finals':['ATP','#23926a'],'NBA':['NBA','#c96a26'],'CS2 · Major':['CS2','#9c7f2a']};
function leagueGlyph(l:string){const [code,color]=leagueMeta[l]??[l.slice(0,2).toUpperCase(),'#35505a'];return `<span class="league-glyph" style="--league:${color}" aria-hidden="true">${esc(code)}</span>`;}
function star(key:string,label:string){return `<button class="icon-button follow ${favorite(key)?'is-followed':''}" data-action="follow" data-key="${esc(key)}" aria-label="${favorite(key)?'Unfollow':'Follow'} ${esc(label)}" aria-pressed="${favorite(key)}">${icon('star')}</button>`;}
function badge(f:Fixture,home=true,large=false){return `<span class="club-badge ${large?'large':''}" style="--club:${f.colors[home?0:1]}" aria-hidden="true"><span>${esc(home?f.homeCode:f.awayCode)}</span></span>`;}
function liveLabel(f:Fixture){return isLive(f)?`<span class="live-label"><i></i>Live<span class="fixture-clock" data-clock="${f.id}">${esc(clockText(f))}</span></span>`:`<span class="fixture-time">${dayOf(f)} <b>${kickoff(f)}</b></span>`;}
function odds(f:Fixture,m:Market,o:Outcome,compact=false){const selected=state.selections.some(p=>p.fixtureId===f.id&&p.marketId===m.id&&p.outcomeId===o.id);const direction=o.previous?o.odds>o.previous?'up':'down':'';return `<button class="odds ${selected?'selected':''} ${direction} ${m.suspended?'suspended':''} ${compact?'compact':''}" data-action="odds" data-fixture="${f.id}" data-market="${m.id}" data-outcome="${o.id}" ${m.suspended||busy?'disabled':''} aria-pressed="${selected}" aria-label="${esc(o.label)}, ${esc(m.name)}, ${m.suspended?'market suspended':`${o.odds.toFixed(2)}${direction?`, odds ${direction==='up'?'increased':'decreased'}`:''}`}"><span class="odds-name">${esc(o.label)}</span><strong>${m.suspended?icon('lock'):`${o.odds.toFixed(2)}${direction?`<span class="movement" aria-hidden="true">${direction==='up'?'▲':'▼'}</span>`:''}`}</strong>${selected?`<span class="selection-tick">${icon('check')}</span>`:''}</button>`;}
function navLinks(){const active=sectionPage();return `<a class="nav-link ${active==='sports'&&!onlyFavorites?'active':''}" ${active==='sports'&&!onlyFavorites?'aria-current="page"':''} href="#/sports">${icon('home')}<span>Sports home</span></a><a class="nav-link ${active==='live'?'active':''}" ${active==='live'?'aria-current="page"':''} href="#/live">${icon('live')}<span>Live</span><b class="nav-count live">${liveCount()}</b></a><a class="nav-link ${active==='football'?'active':''}" ${active==='football'?'aria-current="page"':''} href="#/football">${icon('ball')}<span>Football</span></a><a class="nav-link ${active==='bets'?'active':''}" ${active==='bets'?'aria-current="page"':''} href="#/bets">${icon('ticket')}<span>My Bets</span>${openBets()?`<b class="nav-count">${openBets()}<span class="sr-only"> open</span></b>`:''}</a>`;}
function sidebar(){return `<aside class="sidebar" aria-label="Sports navigation"><nav aria-label="Sportsbook pages">${navLinks()}</nav><button class="nav-link ${onlyFavorites?'active':''}" data-action="favorites" aria-pressed="${onlyFavorites}">${icon('star')}<span>Following</span><span class="nav-count">${state.favorites.length}</span></button><div class="nav-divider"></div><div class="sidebar-label">Top competitions</div>${leagues.map(l=>`<button class="league-nav ${competition===l&&routeName()==='football'?'chosen':''}" data-action="league" data-league="${l}">${leagueGlyph(l)}<span>${l}</span></button>`).join('')}<div class="nav-divider"></div><div class="sidebar-label">More sports</div>${['Tennis','Basketball','Esports'].map(s=>`<button class="nav-link" data-action="sport" data-sport="${s}">${icon(sportIcon(s))}<span>${s}</span></button>`).join('')}<div class="sidebar-bottom"><span class="edition">HOUSE<span>//</span>LIVE</span><p>Sportsbook concept · Sample data</p><button class="demo-trigger" data-action="demo">${icon('settings')} Demo controls</button></div></aside>`;}
function header(){return `<header class="topbar"><div class="brand-wrap"><a class="brand" href="#/sports" aria-label="Housebets Sports home">${brandMark()}<span class="wordmark"><b>H</b>ousebets</span></a><nav class="product-switch" aria-label="Housebets products"><button data-action="info" data-panel="Casino">${icon('casino')}<span>Casino</span></button><a href="#/sports" class="active" aria-current="true">${icon('ball')}<span>Sports</span></a></nav></div><div class="header-actions"><span class="demo-badge" title="Sample data and a simulated balance">Demo</span><button class="wallet" data-action="wallet" aria-label="Demo wallet, ${money(state.balance)} USDT">${icon('coin','coin')}<strong>${money(state.balance)}</strong><span>USDT</span>${icon('down')}</button><button class="button primary deposit" data-action="wallet" aria-label="Deposit (disabled in this demo)">${icon('plus')}<span>Deposit</span></button><button class="avatar" data-action="info" data-panel="Profile" aria-label="Demo profile">${icon('profile')}</button></div></header>`;}
function searchbar(){return `<div class="search-row"><div class="search-box" role="search">${icon('search')}<input id="global-search" data-focus="search" type="search" enterkeyhint="search" placeholder="Search teams, players, competitions or markets" aria-label="Search teams, players, competitions or markets" value="${esc(query)}" autocomplete="off">${query?`<button type="button" class="icon-button clear-search" data-action="clear-search" aria-label="Clear search">${icon('close')}</button>`:'<kbd aria-hidden="true">/</kbd>'}</div><button class="icon-button mobile-demo" data-action="demo" aria-label="Open demo controls">${icon('settings')}</button></div>`;}
function pageTabs(){const active=sectionPage();return `<nav class="page-tabs" aria-label="Sportsbook pages">${([['/sports','Home','sports'],['/live','Live','live'],['/football','Football','football'],['/bets','My Bets','bets']] as const).map(([href,label,name])=>`<a href="#${href}" class="${active===name?'active':''}" ${active===name?'aria-current="page"':''}>${label}${name==='live'?`<b class="live">${liveCount()}</b>`:name==='bets'&&state.selections.length?`<b>${state.selections.length}</b>`:''}</a>`).join('')}</nav>`;}
function sportsNav(liveOnly=false){const pool=liveOnly?state.fixtures.filter(isLive):state.fixtures;return `<nav class="sport-tabs" aria-label="Filter by sport">${['All sports','Football','Tennis','Basketball','Esports'].map(s=>`<button class="sport-tab ${sport===s?'active':''}" data-action="filter-sport" data-sport="${s}" aria-pressed="${sport===s}">${icon(s==='All sports'?'home':sportIcon(s))}${s}<span>${s==='All sports'?pool.length:pool.filter(f=>f.sport===s).length}</span></button>`).join('')}</nav>`;}
function pageHeading(eyebrow:string,title:string,sub:string,action=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1 tabindex="-1" id="page-title">${title}</h1><p>${sub}</p></div>${action}</div>`;}
function hero(){const f=state.fixtures[0];const live=isLive(f);return `<section class="hero" aria-label="Featured ${live?'live':'upcoming'} match"><div class="hero-top"><span class="hero-league">${leagueGlyph(f.league)}<span><b>The main event</b><small>${esc(f.league)} · Emirates Stadium</small></span></span>${liveLabel(f)}</div><div class="hero-body"><div class="hero-copy"><h2>The game.<br>The moment.<br><em>Your house.</em></h2><a class="hero-link" href="#/match/${f.id}">Enter Match Center ${icon('arrow')}</a></div><a class="hero-fixture" href="#/match/${f.id}" aria-label="Open ${esc(f.home)} versus ${esc(f.away)} Match Center"><span class="hero-team">${badge(f,true,true)}<b>${esc(f.home)}</b></span><span class="hero-score"><strong>${live?f.score[0]:'–'}<i>:</i>${live?f.score[1]:'–'}</strong><span data-period="${f.id}">${esc(period(f))}</span></span><span class="hero-team">${badge(f,false,true)}<b>${esc(f.away)}</b></span></a></div><div class="hero-bottom"><span>Match result</span><div class="odds-grid">${f.markets[0].outcomes.map(o=>odds(f,f.markets[0],o,true)).join('')}</div><a href="#/match/${f.id}" class="all-markets">${f.markets.length} markets ${icon('chevron')}</a></div></section>`;}
function fixtureRow(f:Fixture){const reason=query?searchReason(f,query):'';return `<article class="fixture-row ${isLive(f)?'is-live':''}"><div class="row-time">${liveLabel(f)}</div><a class="row-match" href="#/match/${f.id}" aria-label="Open ${esc(f.home)} versus ${esc(f.away)}"><span>${badge(f)}<b>${esc(f.home)}</b><strong>${isLive(f)?f.score[0]:''}</strong></span><span>${badge(f,false)}<b>${esc(f.away)}</b><strong>${isLive(f)?f.score[1]:''}</strong></span>${reason?`<em class="match-reason">${esc(reason)}</em>`:''}</a>${star(`team:${f.home}`,f.home)}<div class="odds-grid">${f.markets[0].outcomes.map(o=>odds(f,f.markets[0],o,true)).join('')}</div><a class="more-markets" href="#/match/${f.id}" aria-label="View ${f.markets.length} markets for ${esc(f.home)} versus ${esc(f.away)}">+${f.markets.length}${icon('chevron')}</a></article>`;}
function fixtureGroups(fixtures:Fixture[]){return [...new Set(fixtures.map(f=>f.league))].map(l=>{const group=fixtures.filter(f=>f.league===l);return `<section class="fixture-group"><div class="group-heading">${leagueGlyph(l)}<h3><span>${esc(group[0].country)} · </span>${esc(l)}</h3><span class="group-count">${plural(group.length,'match')}</span>${star(`league:${l}`,l)}</div>${group.map(fixtureRow).join('')}</section>`;}).join('');}
function empty(title:string,description:string,button='Clear filters',action='clear-filters',art='search'){return `<div class="empty-state">${icon(art)}<h3>${title}</h3><p>${description}</p><button class="button secondary" data-action="${action}">${button}</button></div>`;}
function skeleton(){return `<div class="loading-state" role="status"><div class="loading-label"><span class="spinner" aria-hidden="true"></span> Loading matches…</div>${'<div class="skeleton-row" aria-hidden="true"><i></i><i></i><i></i><i></i></div>'.repeat(4)}</div>`;}
function filters(football=false){return `<div class="filter-row"><div class="segmented" role="group" aria-label="Filter by day">${['All','Today','Tomorrow'].map(d=>`<button data-action="day" data-day="${d}" class="${day===d?'active':''}" aria-pressed="${day===d}">${d}</button>`).join('')}</div><label class="select-label"><span class="sr-only">Competition</span><select id="competition-filter" aria-label="Competition"><option>All competitions</option>${[...new Set(state.fixtures.filter(f=>!football||f.sport==='Football').map(f=>f.league))].map(l=>`<option ${competition===l?'selected':''}>${esc(l)}</option>`).join('')}</select></label><button class="filter-follow ${onlyFavorites?'active':''}" data-action="toggle-following" aria-pressed="${onlyFavorites}">${icon('star')} Following</button></div>`;}
function filtered(fixtures:Fixture[]){let list=searchFixtures(fixtures,query);if(sport!=='All sports')list=list.filter(f=>f.sport===sport);if(competition!=='All competitions')list=list.filter(f=>f.league===competition);if(day!=='All')list=list.filter(f=>dayOf(f)===day);if(onlyFavorites)list=list.filter(f=>favorite(`team:${f.home}`)||favorite(`team:${f.away}`)||favorite(`league:${f.league}`));return list;}
function competitionGrid(){return `<div class="competition-grid">${leagues.map(l=>{const n=state.fixtures.filter(f=>f.league===l).length;return `<button data-action="league" data-league="${l}">${leagueGlyph(l)}<span><b>${l}</b><small>${plural(n,'match')}</small></span>${icon('chevron')}</button>`;}).join('')}</div>`;}
function listPage(){const page=routeName();const football=page==='football',live=page==='live';const constrained=query||sport!=='All sports'||competition!=='All competitions'||day!=='All'||onlyFavorites;const title=football?'Football':live?'Live. In the moment.':onlyFavorites?'Your house. Your teams.':'Welcome to your house.';let list=filtered(state.fixtures.filter(f=>!football||f.sport==='Football'));let fallback=false;if(live){const inplay=list.filter(f=>f.live&&!state.noLive);fallback=inplay.length===0;list=fallback?list.filter(f=>!f.live||state.noLive):inplay;}
 return `${pageHeading(football?'The beautiful game':live?'Every second counts':'Housebets Sports',title,football?'Five top leagues. Match result odds on every row.':live?'Every match in play. Every market within reach.':'Live action, the next kickoff and your teams — one place to call home.',live?`<span class="live-total"><i></i>${liveCount()} in play</span>`:'')}${!football?sportsNav(live):`<nav class="league-tabs" aria-label="Football competitions">${leagues.map(l=>`<button class="${competition===l?'active':''}" data-action="league-filter" data-league="${l}" aria-pressed="${competition===l}">${leagueGlyph(l)}${l}</button>`).join('')}</nav>`}${!live&&!football&&!constrained?hero():''}${football?`<div class="football-banner"><div><span class="eyebrow">Five leagues. Endless moments.</span><h2>Follow the badge.<br>Feel every match.</h2><p>Tap ${icon('star')} to follow a team or competition. Find them again under Following.</p></div><div class="league-art" aria-hidden="true">${icon('ball')}</div></div>`:''}${filters(football)}${loading?skeleton():query?`<div class="section-heading"><h2>${icon('search')} Search results</h2><span>${plural(list.length,'match')} for “${esc(query)}”</span></div>${list.length?fixtureGroups(list):empty('No matches found','Try a team, player, competition or market — for example Arsenal, Marlow, LaLiga or corners.','Clear search','clear-search')}`:live?`${fallback?`<div class="fallback-note" role="status">${icon('clock')}<div><b>No live matches${constrained?' match your filters':' right now'}.</b><span>Keep the next kickoff in sight — starting soon is below.</span></div></div>`:''}<div class="section-heading"><h2>${fallback?`${icon('clock')} Starting soon`:'<i class="live-dot"></i> In play'}</h2><span>${plural(list.length,'match')} · Decimal odds</span></div>${list.length?fixtureGroups(list):empty('Nothing here yet','Change your filters to find more matches.')}`:football||constrained?`${list.length?fixtureGroups(list):empty('No matches found',onlyFavorites?'Follow a team or competition to build your matchday.':'Try another sport, competition or day.',onlyFavorites?'Show all matches':'Clear filters',onlyFavorites?'clear-filters':'clear-filters',onlyFavorites?'star':'search')}`:`<div class="section-heading"><h2><i class="live-dot"></i> Live now <span class="count-pill">${liveCount()}</span></h2><a href="#/live">View all ${icon('arrow')}</a></div>${state.noLive?empty('The next whistle is coming','No matches are in play. Explore starting soon below.','Show upcoming','upcoming','clock'):fixtureGroups(list.filter(f=>f.live))}<div class="section-heading" id="starting-soon"><h2>${icon('clock')} Starting soon</h2><span>Times shown in UTC</span></div>${fixtureGroups(list.filter(f=>!f.live))}<div class="section-heading"><h2>${icon('trophy')} Top competitions</h2></div>${competitionGrid()}`}`;
}
function marketGroup(f:Fixture,m:Market){return `<section class="market-group ${m.suspended?'market-paused':''}" aria-label="${esc(m.name)}"><div class="market-heading"><h3>${esc(m.name)}</h3>${m.suspended?`<span class="suspended-label">${icon('lock')} Suspended</span>`:`<span class="market-format">${plural(m.outcomes.length,'outcome')}</span>`}</div>${m.suspended?'<p class="market-message">Prices are under review. Picks already in your slip are kept; this market reopens shortly.</p>':''}<div class="odds-grid">${m.outcomes.map(o=>odds(f,m,o)).join('')}</div></section>`;}
function matchPage(){const f=currentFixture();const live=isLive(f);const available=categories.filter(c=>f.markets.some(m=>m.category===c));if(!available.includes(category))category=available[0];const shown=f.markets.filter(m=>m.category===category);return `<nav class="breadcrumbs" aria-label="Breadcrumb"><a href="#/sports">Sports</a>${icon('chevron')}<a href="${f.sport==='Football'?'#/football':'#/live'}">${f.sport}</a>${icon('chevron')}<span>${esc(f.league)}</span></nav><section class="match-scoreboard ${live?'is-live':''}" aria-label="Scoreboard"><div class="scoreboard-top"><span class="scoreboard-league">${leagueGlyph(f.league)}${esc(f.league)}</span>${liveLabel(f)}</div><h1 id="page-title" tabindex="-1" class="sr-only">${esc(f.home)} v ${esc(f.away)}</h1><div class="scoreboard-teams"><div class="scoreboard-team">${badge(f,true,true)}<b class="team-name">${esc(f.home)}</b>${star(`team:${f.home}`,f.home)}</div><div class="scoreboard-score" ${live?'aria-label="Score"':''}><strong>${live?f.score[0]:'–'}<i>:</i>${live?f.score[1]:'–'}</strong><span class="scoreboard-period" data-period="${f.id}">${esc(period(f))}</span></div><div class="scoreboard-team">${badge(f,false,true)}<b class="team-name">${esc(f.away)}</b>${star(`team:${f.away}`,f.away)}</div></div><div class="scoreboard-bottom"><span>${f.id==='ars-bha'?'Emirates Stadium · London':`${esc(f.country)} · Sample fixture`}</span><span>${icon('shield')} Simulated ${live?'live':'upcoming'} event</span></div></section><div class="match-context"><span class="${live&&liveFeed?'feed-on':''}">${live?`<i class="live-dot"></i> ${liveFeed?'Live prices updating':'Live prices paused'}`:`${icon('clock')} Pre-match markets`}</span><span>Decimal odds · Singles only</span></div><nav class="market-tabs match-tabs-sticky" aria-label="Market categories">${available.map(c=>`<button data-action="category" data-category="${c}" aria-pressed="${category===c}" class="${category===c?'active':''}">${c}<span>${f.markets.filter(m=>m.category===c).length}</span></button>`).join('')}</nav><div class="section-heading"><h2>${category==='Popular'?'The match essentials':category}</h2><span>${plural(shown.length,'market')}</span></div>${shown.map(m=>marketGroup(f,m)).join('')}<div class="market-note">${icon('info')}<p>Prices are simulated and move during live play. If a price you picked changes, you decide whether to accept it before your bet is placed.</p></div><div class="next-match"><span>Keep the matchday going</span><a href="#/match/${f.id==='liv-mun'?'rma-bay':'liv-mun'}">${f.id==='liv-mun'?'Real Madrid v Bayern Munich':'Liverpool v Manchester United'} ${icon('arrow')}</a></div>`;}
const pickKey=(p:Selection)=>`${p.fixtureId}:${p.marketId}:${p.outcomeId}`;
function selectionCard(p:Selection,scope:string){const r=resolve(state,p);if(!r)return '';const changed=r.outcome.odds!==p.acceptedOdds;const id=`stake-${scope}-${pickKey(p)}`;const value=stakeValue(p.stake);const invalid=!Number.isFinite(value)||value<1||value>1000;const displayOdds=changed?r.outcome.odds:p.acceptedOdds;const displayReturn=Number.isFinite(value)?round(value*displayOdds):0;return `<article class="selection-card ${changed&&!r.market.suspended?'price-changed':''} ${r.market.suspended?'selection-suspended':''}"><div class="selection-top"><span>${isLive(r.fixture)?'<i class="live-dot"></i>Live':icon('clock')+'Pre-match'} · Single</span><button class="icon-button remove-selection" data-action="remove" data-key="${pickKey(p)}" aria-label="Remove ${esc(r.outcome.label)}" ${busy?'disabled':''}>${icon('close')}</button></div><div class="pick-name"><strong>${esc(r.outcome.label)}</strong><b class="${changed?'changed-price':''}">${displayOdds.toFixed(2)}${changed?'<small>new</small>':''}</b></div><span class="pick-market">${esc(r.market.name)}</span><a href="#/match/${r.fixture.id}" class="pick-fixture">${esc(r.fixture.home)} v ${esc(r.fixture.away)} ${icon('chevron')}</a>${r.market.suspended?`<div class="state-message suspended" role="status">${icon('lock')}<span><b>Market suspended.</b> Your pick is saved; placement is paused until it reopens.</span></div>`:changed?`<div class="state-message warning" role="status">${icon('refresh')}<span><b>Odds changed</b> <s>${p.acceptedOdds.toFixed(2)}</s> → <b>${r.outcome.odds.toFixed(2)}</b>. Accept to continue.</span></div>`:''}<label class="stake-label" for="${id}">Stake <span>1–1,000 USDT</span></label><div class="stake-input ${invalid?'invalid':''}"><input id="${id}" data-focus="${id}" data-stake="${pickKey(p)}" aria-label="Stake for ${esc(r.outcome.label)} in USDT" aria-invalid="${invalid}" ${invalid?`aria-describedby="${id}-error"`:''} type="text" inputmode="decimal" enterkeyhint="done" autocomplete="off" value="${esc(p.stake)}" ${busy?'disabled':''}><span>USDT</span></div><div class="quick-stakes">${[10,25,50,100].map(n=>`<button data-action="stake" data-key="${pickKey(p)}" data-value="${n}" aria-label="Set stake to ${n} USDT" aria-pressed="${p.stake===String(n)}" class="${p.stake===String(n)?'active':''}" ${busy?'disabled':''}>${n}</button>`).join('')}</div><div class="selection-return ${changed?'review-return':''}"><span>${changed?'Return after acceptance':'Potential return'}</span><strong>${money(displayReturn)} <small>USDT</small></strong></div>${invalid?`<p class="input-error" id="${id}-error">${icon('info')}Stake must be 1–1,000 USDT, with up to 2 decimals.</p>`:''}</article>`;}
function noticeView(){if(!notice)return '';const dismiss=`<button data-action="dismiss-notice" class="icon-button" aria-label="Dismiss notification">${icon('close')}</button>`;if(notice.kind==='success'){const bets=notice.bets??[];return `<div class="notice success" role="status">${icon('check')}<div class="notice-body"><b>Bet placed. You’re in.</b><p>${esc(notice.message)}</p>${bets.length?`<ul class="receipt">${bets.map(b=>`<li><span><strong>${esc(b.outcome)}</strong><small>${esc(b.market)} · ${esc(b.fixture)}</small></span><span><b>${b.odds.toFixed(2)}</b><small>${money(b.stake)} → ${money(b.return)} USDT</small></span></li>`).join('')}</ul>`:''}<button data-action="view-open" class="text-button">View in My Bets ${icon('arrow')}</button></div>${dismiss}</div>`;}return `<div class="notice error" role="alert">${icon('info')}<div class="notice-body"><b>Bet not placed</b><p>${esc(notice.message.replace(/^Bet not placed\.\s*/,''))}</p>${placementError(state)?'':`<button data-action="place" class="button secondary retry" ${busy?'disabled':''}>${icon('refresh')} Try again</button>`}</div>${dismiss}</div>`;}
function slipContent(scope='rail'){const n=state.selections.length;const resolved=state.selections.map(p=>({p,r:resolve(state,p)}));const changed=resolved.filter(({p,r})=>r&&r.outcome.odds!==p.acceptedOdds&&!r.market.suspended).length;const suspended=resolved.filter(({r})=>r?.market.suspended).length;const blocked=placementError(state);const reviewTotal=changed?currentReturn():totalReturn(state);return `<div class="slip-header"><h2>Betslip <span class="count-pill">${n}</span></h2><span class="single-badge">Singles only</span></div>${noticeView()}${n?`<div class="slip-toolbar"><span>${plural(n,'separate single bet')}</span><button data-action="clear-slip" ${busy?'disabled':''}>Clear all</button></div>${changed?`<div class="slip-alert warning" role="status">${icon('refresh')}<div><b>Odds changed on ${plural(changed,'selection')}</b><span>Review the new price and return, then accept to continue.</span></div></div>`:''}${suspended?`<div class="slip-alert suspended" role="status">${icon('lock')}<div><b>${plural(suspended,'selection')} suspended</b><span>Placement is paused until the market reopens.</span></div><button class="text-button" data-action="remove-suspended" ${busy?'disabled':''}>Remove</button></div>`:''}<div class="selection-list">${state.selections.map(p=>selectionCard(p,scope)).join('')}</div><div class="slip-summary"><div class="summary-line"><span>Total stake</span><b>${money(totalStake(state))} <small>USDT</small></b></div><div class="summary-line total-return ${changed?'review-return':''}"><span>${changed?'Return after acceptance':'Potential return'}</span><b>${money(reviewTotal)} <small>USDT</small></b></div><p>Each single settles on its own. Returns are added together, never multiplied.</p>${changed?`<button class="button accept-button" data-action="accept" ${busy?'disabled':''}>${icon('refresh')} Accept new odds</button>`:''}${blocked&&!changed?`<p class="placement-hint">${icon('info')}${esc(blocked)}</p>`:''}<button class="button primary place-button" data-action="place" ${blocked||busy?'disabled':''}>${busy?'<span class="spinner"></span> Placing…':`Place ${n===1?'single bet':`${n} single bets`} · ${money(totalStake(state))} USDT`}</button><span class="demo-disclosure">${icon('shield')} Demo balance only · No real money</span></div>`:`<div class="slip-empty"><div class="ticket-art">${icon('ticket')}<span>+</span></div><h3>Your next moment<br>starts here.</h3><p>Tap any odds to add a selection.<br>One match. One pick. Your call.</p><a class="button secondary" href="#/live">Explore live matches ${icon('arrow')}</a><ol class="empty-steps"><li><b>1</b> Pick your odds</li><li><b>2</b> Set your stake in USDT</li><li><b>3</b> Review and place</li></ol></div>`}`;}
function betCard(b:Bet,cashView=false){return `<article class="bet-card ${b.status} ${cashView?'cashout-card':''}"><div class="bet-card-top"><span class="bet-status ${b.status}">${cashView?'Cash out available':b.status==='open'?'Open':b.status==='cashed'?'Cashed out':b.status==='won'?'Won':'Lost'}</span><small>${esc(b.placedAt)}</small></div><a href="#/match/${esc(b.fixtureId)}">${esc(b.fixture)} ${icon('chevron')}</a><div class="bet-outcome"><strong>${esc(b.outcome)}</strong><b>${b.odds.toFixed(2)}</b></div><p>${esc(b.market)} · Single</p><div class="bet-values"><span>Stake<b>${money(b.stake)} USDT</b></span><span>${cashView?'Offer':b.status==='open'?'Potential return':'Returned'}<b>${money(cashView?b.cashOffer:b.return)} USDT</b></span></div>${b.status==='open'?`<button class="cash-button" data-action="cash" data-id="${esc(b.id)}" aria-haspopup="dialog">${icon('coin')}<span>${cashView?'Cash out now':'Cash out'}</span><strong>${money(b.cashOffer)} USDT</strong></button>`:''}<small class="bet-reference">Ref ${esc(b.id)}</small></article>`;}
function historyContent(){const open=state.bets.filter(b=>b.status==='open');const settled=state.bets.filter(b=>b.status!=='open');const cashable=open.filter(b=>b.cashOffer>0);const cashView=historyTab==='Cash Out';const bets=historyTab==='Settled'?settled:cashView?cashable:open;const counts:Record<string,number>={Open:open.length,Settled:settled.length,'Cash Out':cashable.length};return `<div class="history-heading"><h2>My Bets</h2><span>${icon('shield')} Simulated</span></div><div class="history-tabs" role="tablist" aria-label="Bet history">${['Open','Settled','Cash Out'].map(t=>`<button role="tab" data-focus="history-${t.replaceAll(' ','-')}" id="history-${t.replaceAll(' ','-')}" aria-controls="history-panel" tabindex="${historyTab===t?0:-1}" aria-selected="${historyTab===t}" class="${historyTab===t?'active':''}" data-action="history" data-tab="${t}">${t} <span>${counts[t]}</span></button>`).join('')}</div><div id="history-panel" class="${cashView?'cashout-panel':''}" role="tabpanel" aria-labelledby="history-${historyTab.replaceAll(' ','-')}" tabindex="0">${cashView&&bets.length?`<p class="history-note">${icon('info')}Lock in a return before the final whistle. Offers are simulated and always need your confirmation.</p>`:''}${bets.length?bets.map(b=>betCard(b,cashView)).join(''):empty(historyTab==='Open'?'A clean slate.':cashView?'No bets available to cash out.':'Your results will live here.','Explore a match and place a simulated single bet.','Find a match','find-match','ticket')}</div>`;}
function betsPage(){return `${pageHeading('Your matchday, all in one place','Betslip & My Bets','Every selection. Every result. Always in your hands.')}<div class="bets-workspace"><section class="bets-slip" aria-label="Betslip">${slipContent('page')}</section><section class="history" aria-label="My Bets">${historyContent()}</section></div>`;}
function rail(){return `<aside class="right-rail" aria-label="Betslip side panel">${routeName()==='bets'?`<div class="session-card"><div class="eyebrow">Your demo session</div>${icon('coin')}<h2>${money(state.balance)} <small>USDT</small></h2><p>Simulated balance</p><div><span>Open bets</span><b>${state.bets.filter(b=>b.status==='open').length}</b></div><div><span>Following</span><b>${state.favorites.length}</b></div><button class="button secondary" data-action="demo">${icon('settings')} Explore demo scenarios</button></div>`:`<div class="rail-tabs"><span class="active">Betslip</span><a href="#/bets">My Bets <b>${state.bets.filter(b=>b.status==='open').length}</b></a></div>${slipContent()}`}<div class="rail-footnote">${icon('shield')} A considered bet starts with clarity.<br>All transactions in this concept are simulated.</div></aside>`;}
function mobileBar(){const n=state.selections.length;const attention=state.selections.some(p=>{const r=resolve(state,p);return !r||r.market.suspended||r.outcome.odds!==p.acceptedOdds;});return `<div class="mobile-slip-bar"><button data-action="mobile-slip" aria-haspopup="dialog" aria-label="Open betslip, ${plural(n,'selection')}${n?`, potential return ${money(totalReturn(state))} USDT`:''}${attention?', needs your review':''}"><span class="bar-ticket">${icon('ticket')}<b>${n}</b></span><span class="bar-copy"><strong>Betslip</strong><small class="${attention?'attention':''}">${attention?'Review needed · odds changed or suspended':n?`${plural(n,'single')} · ${money(totalStake(state))} USDT stake`:'Tap any odds to add a pick'}</small></span><span class="bar-return">${n?`<small>Potential return</small><strong>${money(totalReturn(state))}</strong>`:icon('arrow')}</span></button></div>`;}
function bottomNav(){return `<nav class="bottom-nav" aria-label="Housebets mobile navigation"><button data-action="menu" aria-haspopup="dialog">${icon('menu')}<span>Menu</span></button><a href="#/sports" class="active" aria-current="true">${icon('ball')}<span>Sports</span></a><button data-action="info" data-panel="Casino" aria-haspopup="dialog">${icon('casino')}<span>Casino</span></button><button data-action="info" data-panel="Chat" aria-haspopup="dialog">${icon('chat')}<span>Chat</span></button><button data-action="search">${icon('search')}<span>Search</span></button></nav>`;}
function demoContent(){return `<div class="eyebrow">Judge’s control room</div><h2>Every state. On demand.</h2><p class="dialog-intro">Sample data, simulated transactions. Price and suspension changes target your first selection, or Arsenal’s match result when the slip is empty.</p><div class="demo-grid"><button data-action="move">${icon('refresh')}<b>Move odds</b><span>Require explicit acceptance</span></button><button data-action="suspend">${icon('lock')}<b>Suspend / reopen</b><span>Keep the selection in place</span></button><button data-action="fail" class="${state.failNext?'armed':''}">${icon('info')}<b>${state.failNext?'Failure armed':'Fail next placement'}</b><span>${state.failNext?'Click again to disarm':'Balance stays untouched'}</span></button><button data-action="settle">${icon('check')}<b>Settle an open bet</b><span>Move to won, credit return</span></button><button data-action="no-live" class="${state.noLive?'armed':''}">${icon('clock')}<b>${state.noLive?'Restore live matches':'No live matches'}</b><span>Show Starting Soon fallback</span></button><button data-action="loading">${icon('refresh')}<b>Loading state</b><span>Two-second match loading demo</span></button><button data-action="feed" class="${liveFeed?'':'armed'}">${icon('live')}<b>${liveFeed?'Pause live prices':'Resume live prices'}</b><span>In-play prices drift every few seconds</span></button></div><div class="demo-footer"><span>Reset restores 1,000 USDT and sample history.</span><button class="text-button" data-action="reset-confirm">Reset demo</button></div>`;}
function infoContent(){if(infoPanel==='Profile')return `<div class="eyebrow">Demo profile</div><div class="profile-head"><span class="avatar large" aria-hidden="true">${icon('profile')}</span><div><h2>Guest player</h2><p>Simulated session · no Housebets account connected</p></div></div><dl class="profile-stats"><div><dt>Demo balance</dt><dd>${money(state.balance)} USDT</dd></div><div><dt>Open bets</dt><dd>${state.bets.filter(b=>b.status==='open').length}</dd></div><div><dt>Following</dt><dd>${state.favorites.length}</dd></div></dl><div class="profile-actions"><button class="button secondary" data-action="view-open">${icon('ticket')} My Bets</button><button class="button secondary" data-action="favorites">${icon('star')} Following</button><button class="button secondary" data-action="demo">${icon('settings')} Demo controls</button></div><p class="dialog-intro">Followed teams, bet history and the demo balance are stored in this browser only.</p>`;const casino=infoPanel==='Casino';return `<div class="eyebrow">${casino?'Casino':'Chat'} · Outside this prototype</div><h2>${casino?'Tonight, the sportsbook is the main event.':'Chat isn’t part of this prototype.'}</h2><p>${casino?'Casino sits in the Housebets navigation, but this contest entry covers the five sportsbook pages only. No casino games or real-money play are available here.':'Community chat is outside the contest scope, so no messages are sent or received. The side panel stays dedicated to your betslip.'}</p><button class="button primary" data-action="close">Back to Sports ${icon('arrow')}</button>`;}
function dialog(){const cash=state.bets.find(b=>b.id===cashId);if(!panelOpen())return '';let body='';let label='';if(infoPanel){label=infoPanel==='Profile'?'Demo profile':`${infoPanel} — outside this prototype`;body=infoContent();}else if(resetOpen){label='Reset demo';body=`<div class="eyebrow">Reset · Demo</div><h2>Start a fresh matchday?</h2><p>Your local demo picks, favorites and bet history will reset to the sample session.</p><button class="button primary" data-action="reset">Reset demo session</button>`;}else if(cash){label='Confirm cash out';body=`<div class="eyebrow">Cash out · Demo</div><h2>Lock in this return?</h2><p>${esc(cash.outcome)} · ${esc(cash.market)}<br>${esc(cash.fixture)}</p><div class="cash-amount">${money(cash.cashOffer)} <small>USDT</small></div><p>The bet settles immediately and this amount returns to your demo balance. Stake was ${money(cash.stake)} USDT; full potential return ${money(cash.return)} USDT.</p><button class="button primary" data-action="confirm-cash" data-id="${esc(cash.id)}">Confirm cash out ${icon('check')}</button>`;}else if(demoOpen){label='Demo scenarios';body=demoContent();}else if(walletOpen){label='Demo wallet';body=`<div class="eyebrow">Demo wallet</div><h2>Your practice balance.</h2><div class="cash-amount">${money(state.balance)} <small>USDT</small></div><p>Deposits and withdrawals are switched off. This is a frontend prototype with no player accounts, payments or real-money transactions.</p><button class="button secondary" data-action="view-open">View My Bets ${icon('arrow')}</button>`;}else if(menuOpen){label='Navigation';body=`<a class="brand" href="#/sports">${brandMark()}<span class="wordmark"><b>H</b>ousebets</span></a><nav class="drawer-nav" aria-label="Sportsbook pages">${navLinks()}</nav><button class="nav-link" data-action="favorites">${icon('star')}<span>Following</span><span class="nav-count">${state.favorites.length}</span></button><div class="sidebar-label">Top competitions</div>${leagues.map(l=>`<button class="league-nav" data-action="league" data-league="${l}">${leagueGlyph(l)}<span>${l}</span></button>`).join('')}<div class="nav-divider"></div><button class="nav-link" data-action="info" data-panel="Profile">${icon('profile')}<span>Demo profile</span></button><button class="nav-link" data-action="demo">${icon('settings')}<span>Demo controls</span></button>`;}else {label='Betslip';body=`${slipContent('sheet')}<a class="panel-history-link" href="#/bets">Betslip & My Bets ${icon('arrow')}</a>`;}return `<dialog class="modal ${mobileOpen?'slip-modal':''} ${menuOpen?'menu-modal':''}" aria-label="${esc(label)}"><button class="modal-close icon-button" data-action="close" aria-label="Close panel">${icon('close')}</button>${body}</dialog>`;}
function closePanels(){mobileOpen=false;demoOpen=false;menuOpen=false;walletOpen=false;cashId=null;resetOpen=false;infoPanel='';}
function toast(message:string){toastText=message;clearTimeout(toastTimer);toastTimer=setTimeout(()=>{toastText='';document.querySelector('.toast')?.remove();},3500);}
// Views are re-rendered wholesale, so focus is restored by a stable control key rather than by element identity.
const controlKey=(el:HTMLElement)=>el.dataset.focus||el.id||`${el.tagName}|${el.getAttribute('href')??''}|${JSON.stringify(el.dataset)}`;
const controls=(inModal:boolean,key:string)=>Array.from(root.querySelectorAll<HTMLElement>('a,button,input,select,[tabindex]')).filter(e=>!!e.closest('dialog')===inModal&&controlKey(e)===key);
function render(){const active=document.activeElement instanceof HTMLElement&&document.activeElement!==root&&root.contains(document.activeElement)?document.activeElement:null;const where=active?{key:controlKey(active),inModal:!!active.closest('dialog'),index:0}:undefined;if(where&&active)where.index=Math.max(0,controls(where.inModal,where.key).indexOf(active));const input=active instanceof HTMLInputElement?active:null;const start=input?.selectionStart,end=input?.selectionEnd;const oldModal=document.querySelector('dialog');const modalScroll=oldModal?.scrollTop??0;if(!oldModal&&panelOpen()&&where&&!where.inModal)opener=where;const closing=!!oldModal&&!panelOpen();oldModal?.close();const page=routeName();root.innerHTML=`${header()}${sidebar()}<div class="app-layout"><main id="main" tabindex="-1">${searchbar()}${pageTabs()}${page==='match'?matchPage():page==='bets'?betsPage():listPage()}<footer class="main-footer"><span class="edition">HOUSE<span>//</span>LIVE</span><span>A Housebets sportsbook concept<br><small>Sample events and odds · Simulated USDT · All times UTC</small></span></footer></main>${rail()}</div>${mobileBar()}${bottomNav()}${dialog()}${toastText?`<div class="toast" role="status">${icon('check')}${esc(toastText)}</div>`:''}`;const modal=document.querySelector<HTMLDialogElement>('dialog');if(modal){modal.showModal();modal.scrollTop=modalScroll;modal.addEventListener('cancel',e=>{e.preventDefault();closePanels();render();});}let target:HTMLElement|undefined;const find=(inModal:boolean,w:{key:string;index:number})=>{const list=controls(inModal,w.key);return list[w.index]??list[0];};if(modal&&where?.inModal)target=find(true,where);else if(!modal&&where&&!where.inModal)target=find(false,where);else if(!modal&&closing)target=(opener&&find(false,opener))??document.querySelector<HTMLElement>('#page-title')??undefined;if(closing)opener=undefined;if(target){target.focus({preventScroll:true});if(start!==null&&start!==undefined&&target instanceof HTMLInputElement)try{target.setSelectionRange(start,end??start);}catch{/* Search input selection may be unsupported. */}}document.title=`${page==='match'?`${currentFixture().home} v ${currentFixture().away}`:page==='bets'?'Betslip & My Bets':page==='football'?'Football':page==='live'?'Live Sports':'Sports Home'} — HOUSE//LIVE`;save();}
function clearFilters(){query='';sport='All sports';competition='All competitions';day='All';onlyFavorites=false;}
function focusSearch(){const input=root.querySelector<HTMLInputElement>('#global-search');window.scrollTo({top:0});input?.focus({preventScroll:true});}
function refreshOutcome(key:string){const [fid,mid,oid]=key.split(':');const f=state.fixtures.find(x=>x.id===fid);const m=f?.markets.find(x=>x.id===mid);const o=m?.outcomes.find(x=>x.id===oid);if(!f||!m||!o)return;root.querySelectorAll<HTMLButtonElement>(`.odds[data-fixture="${fid}"][data-market="${mid}"][data-outcome="${oid}"]`).forEach(button=>{const template=document.createElement('template');template.innerHTML=odds(f,m,o,button.classList.contains('compact'));const next=template.content.firstElementChild as HTMLButtonElement;
// Patch the live button in place: replacing it mid-press would drop the player's tap.
for(const name of button.getAttributeNames())if(!next.hasAttribute(name))button.removeAttribute(name);for(const name of next.getAttributeNames())if(button.getAttribute(name)!==next.getAttribute(name))button.setAttribute(name,next.getAttribute(name)!);if(button.innerHTML!==next.innerHTML)button.innerHTML=next.innerHTML;});}
root.addEventListener('input',e=>{const input=e.target as HTMLInputElement;if(input.id==='global-search'){query=input.value;if(['match','bets'].includes(routeName()))go('/sports');render();}if(input.dataset.stake){const p=state.selections.find(p=>pickKey(p)===input.dataset.stake);if(p){p.stake=input.value;notice=null;render();}}});
root.addEventListener('change',e=>{const input=e.target as HTMLSelectElement;if(input.id==='competition-filter'){competition=input.value;render();}});
root.addEventListener('click',async e=>{const target=e.target as HTMLElement;const link=target.closest<HTMLAnchorElement>('a[href^="#/"]');if(link){e.preventDefault();const href=link.getAttribute('href')!.slice(1);closePanels();if(link.getAttribute('href')==='#/sports')clearFilters();if(link.getAttribute('href')==='#/football'){clearFilters();sport='Football';}if(link.getAttribute('href')==='#/live')clearFilters();go(href);render();return;}const button=target.closest<HTMLButtonElement>('[data-action]');if(!button||button.disabled)return;const d=button.dataset;switch(d.action){
case 'follow':{const key=d.key!;state.favorites=favorite(key)?state.favorites.filter(k=>k!==key):[...state.favorites,key];toast(favorite(key)?`${key.split(':')[1]} followed`:`${key.split(':')[1]} unfollowed`);break;}
case 'favorites':clearFilters();onlyFavorites=true;closePanels();go('/sports');break;
case 'toggle-following':onlyFavorites=!onlyFavorites;break;
case 'sport':closePanels();clearFilters();sport=d.sport!;go('/sports');break;
case 'filter-sport':sport=d.sport!;competition='All competitions';break;
case 'league':closePanels();clearFilters();sport='Football';competition=d.league!;go('/football');break;
case 'league-filter':competition=competition===d.league?'All competitions':d.league!;break;
case 'day':day=d.day!;break;
case 'clear-filters':clearFilters();break;
case 'clear-search':query='';render();focusSearch();return;
case 'search':closePanels();render();focusSearch();return;
case 'upcoming':document.querySelector('#starting-soon')?.scrollIntoView({behavior:'smooth'});return;
case 'find-match':closePanels();clearFilters();go('/sports');break;
case 'odds':if(!busy){toggleSelection(state,d.fixture!,d.market!,d.outcome!);notice=null;toast(state.selections.some(p=>p.fixtureId===d.fixture&&p.marketId===d.market&&p.outcomeId===d.outcome)?'Selection added to your betslip':'Selection removed');}break;
case 'remove':state.selections=state.selections.filter(p=>pickKey(p)!==d.key);notice=null;break;
case 'remove-suspended':{const n=removeSuspended(state);notice=null;toast(`${plural(n,'suspended selection')} removed`);break;}
case 'clear-slip':state.selections=[];notice=null;break;
case 'stake':{const p=state.selections.find(p=>pickKey(p)===d.key);if(p)p.stake=d.value!;notice=null;break;}
case 'accept':acceptChanges(state);notice=null;toast('New odds accepted. Review your return.');break;
case 'place':{if(busy||placementError(state))return;busy=true;notice=null;render();await new Promise(r=>setTimeout(r,850));const result=placeBets(state);busy=false;notice={kind:result.ok?'success':'error',message:result.message,bets:result.bets?.map(b=>({...b}))};render();return;}
case 'dismiss-notice':notice=null;break;
case 'history':historyTab=d.tab!;break;
case 'view-open':closePanels();historyTab='Open';go('/bets');break;
case 'category':category=d.category as Category;break;
case 'mobile-slip':closePanels();mobileOpen=true;break;
case 'menu':closePanels();menuOpen=true;break;
case 'wallet':closePanels();walletOpen=true;break;
case 'info':closePanels();infoPanel=d.panel as typeof infoPanel;break;
case 'demo':closePanels();demoOpen=true;break;
case 'close':closePanels();break;
case 'move':moveOdds(state);closePanels();toast('Odds moved. Selected prices need your acceptance.');break;
case 'suspend':toggleSuspension(state);closePanels();toast('Market availability updated.');break;
case 'fail':state.failNext=!state.failNext;closePanels();toast(state.failNext?'Next valid placement will fail.':'Placement failure disarmed.');break;
case 'settle':toast(settle(state)?'Open bet settled as won. Demo return credited.':'No open bets to settle.');closePanels();historyTab='Settled';go('/bets');break;
case 'no-live':state.noLive=!state.noLive;closePanels();clearFilters();go('/live');break;
case 'loading':closePanels();clearFilters();go('/live');loading=true;setTimeout(()=>{loading=false;render();},2000);break;
case 'feed':liveFeed=!liveFeed;closePanels();toast(liveFeed?'Live prices resumed.':'Live prices paused.');break;
case 'cash':cashId=d.id!;break;
case 'confirm-cash':if(cashOut(state,d.id!)){toast('Cash out confirmed. Demo balance updated.');historyTab='Settled';}cashId=null;break;
case 'reset-confirm':closePanels();resetOpen=true;break;
case 'reset':state=initialState();elapsed=0;liveFeed=true;notice=null;closePanels();clearFilters();historyTab='Open';toast('Demo session reset.');go('/sports');break;
}render();});
window.addEventListener('hashchange',()=>{closePanels();category='Popular';if(routeName()==='football')sport='Football';else if(routeName()==='live')sport='All sports';render();window.scrollTo({top:0});if(document.activeElement?.id!=='global-search')document.querySelector<HTMLElement>('#page-title')?.focus({preventScroll:true});});
window.addEventListener('keydown',e=>{const target=e.target as HTMLElement;if(e.key==='Escape'&&target.id==='global-search'&&query){e.preventDefault();query='';render();return;}if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(target.tagName)&&!document.querySelector('dialog')){e.preventDefault();focusSearch();}});
setInterval(()=>{elapsed++;for(const f of state.fixtures)if(isLive(f)&&ticking(f)){root.querySelectorAll(`[data-clock="${f.id}"]`).forEach(el=>el.textContent=clockText(f));root.querySelectorAll(`[data-period="${f.id}"]`).forEach(el=>el.textContent=period(f));}},1000);
setInterval(()=>{if(!liveFeed||busy||loading||document.hidden)return;const onScreen=new Set(Array.from(root.querySelectorAll<HTMLElement>('main .odds')).map(el=>`${el.dataset.fixture}:${el.dataset.market}`));const change=driftOdds(state,Math.random,(fixtureId,marketId)=>onScreen.has(`${fixtureId}:${marketId}`));if(!change)return;change.cleared.forEach(refreshOutcome);const key=`${change.fixtureId}:${change.marketId}:${change.outcomeId}`;refreshOutcome(key);root.querySelectorAll<HTMLElement>(`.odds[data-fixture="${change.fixtureId}"][data-market="${change.marketId}"][data-outcome="${change.outcomeId}"]`).forEach(el=>{void el.offsetWidth;el.classList.add('flash');});},3500);
render();

document.querySelector('.skip-link')?.addEventListener('click', event => { event.preventDefault(); const main = document.querySelector<HTMLElement>('#main'); main?.focus(); main?.scrollIntoView({ block: 'start' }); });

root.addEventListener('keydown', event => {
 const target = event.target as HTMLElement;
 if (!target.matches('[data-action="history"]') || !['ArrowLeft','ArrowRight','Home','End'].includes(event.key)) return;
 event.preventDefault();
 const tabs = ['Open','Settled','Cash Out'];
 const next = event.key === 'Home' ? 0 : event.key === 'End' ? 2 : (tabs.indexOf(historyTab) + (event.key === 'ArrowRight' ? 1 : 2)) % 3;
 historyTab = tabs[next];
 render();
 document.getElementById(`history-${historyTab.replaceAll(' ','-')}`)?.focus();
});
